#part_page("VI", [ऑटोमेटा, ट्राइज़ और सिमेंटिक फ़ायरवॉल], [
  हम अनुरोध वर्गीकरण के एल्गोरिदम का अध्ययन करते हैं: टैग्ड Aho–Corasick ऑटोमेटन, IPv4/IPv6 रेडिक्स ट्राइ (radix trie), सिमेंटिक WAF के बाइट-क्लास टोकनाइज़र्स, और WEIGH स्कोरिंग से युक्त घोषणात्मक नीति इंजन।
])

b822ca3fd9a19cb4:
#objectives([
  इस अध्याय के अध्ययन के बाद आप Aho–Corasick ऑटोमेटन की रैखिक-समय गारंटी (linear-time guarantee) को स्पष्ट कर सकेंगे। डेंस-टेबल लेआउट और कंपाइल-टाइम केस-फ़ोल्डिंग की कार्यप्रणाली समझ सकेंगे, तथा लिटरल मैचर चुनने के ट्रेड-ऑफ़्स का विश्लेषण कर सकेंगे।
])

af588564db1c7847:
#objectives([
  128-बिट ट्राइ में लॉन्गेस्ट-प्रीफ़िक्स लुकअप का प्रवाह समझें। IPv4 रूट शॉर्टकट का विश्लेषण करें और जानें कि क्लस्टर से प्राप्त होने वाला प्रतिष्ठा डेटा (reputation store) भी इसी ट्राइ संरचना में कैसे समाहित होता है।
])

4eafd8006ce550f1:
#objectives([
  बाइट-क्लास प्री-स्कैन, टैग्ड सिग्नेचर ऑटोमेटन, टॉटोलॉजी पहचान वाला SQL टोकनाइज़र, HTML एवं शेल संरचना जाँच, कैनोनिकलाइज़ेशन और फ़ॉल्स-पॉज़िटिव अनुशासन को समझें। वास्तविक वैध ब्राउज़र अनुरोध बिना किसी बाधा के पार होना चाहिए।
])

4734d8693440400e:
#objectives([
  नियम मॉडल, मूल्यांकन क्रम, थ्रेशोल्ड्स से युक्त WEIGH स्कोरिंग और JSON नीति व्याकरण का अध्ययन करें।
])

a8c0153e428b64da:
#exercise([6.2], [
  LDAP इंजेक्शन (⟦0⟧ पैटर्नों) का डिटेक्टर जोड़ने हेतु बाइट-क्लास टेबल प्रविष्टियाँ लिखें। स्पष्ट करें कि वह किन मौजूदा क्लास बिट्स का पुनः उपयोग कर सकता है।
])

d846fff1d5b57205:
#teach_back([
  समीक्षक को समझाएँ कि ⟦0⟧ एक झूठी चेतावनी (false positive) क्यों थी। नया SQL डिटेक्टर किस संरचनात्मक साक्ष्य की माँग करता है? ऑटोमेटन और टोकनाइज़र कार्य का विभाजन कैसे करते हैं?
])
